class Solution {
    fun numberOfSets(n:Int,k:Int):Int{
        val mod=1_000_000_007L;
        val limit=n+k-1;
        val choose=2*k;
        val combination=Array(limit+1){
            LongArray(choose+1)
        };
        for(row in 0..limit){
            combination[row][0]=1;
            for(col in 1..minOf(row,choose))combination[row][col]=(combination[row-1][col-1]+combination[row-1][col])%mod
        };
        return combination[limit][choose].toInt()
    }
}

code.cpp:
class Solution {
    public: int numberOfSets(int n,int k){
        const long long mod=1000000007;
        int limit=n+k-1,choose=2*k;
        vector<vector<long long>> combination(limit+1,vector<long long>(choose+1));
        for(int row=0;row<=limit;++row){
            combination[row][0]=1;
            for(int col=1;col<=min(row,choose);++col)combination[row][col]=(combination[row-1][col-1]+combination[row-1][col])%mod;
        }
        return combination[limit][choose];
    }
};
